files.examples/01_wal.sql:
-- LEARN(sql.security-ops.backup-migrations): PITR replays the WAL, so what isn't in the WAL can't come back.
-- Every change to an ordinary table is written to the write-ahead log (WAL)
-- first. Archiving ships that log; point-in-time recovery replays it.
CREATE TABLE audit_log (id int PRIMARY KEY, event text NOT NULL);
-- UNLOGGED skips the WAL: faster writes, no crash safety, no recovery.
CREATE UNLOGGED TABLE import_scratch (id int PRIMARY KEY, event text NOT NULL);

-- How many WAL records a statement wrote, from EXPLAIN (ANALYZE, WAL).
CREATE FUNCTION wal_records(stmt text) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE plan json;
BEGIN
  EXECUTE 'EXPLAIN (ANALYZE, WAL, FORMAT JSON) ' || stmt INTO plan;
  RETURN (plan -> 0 -> 'Plan' ->> 'WAL Records')::bigint;
END $$;

SELECT wal_records($$INSERT INTO audit_log
                     SELECT g, 'login ' || g FROM generate_series(1, 1000) AS g$$) AS logged,
       wal_records($$INSERT INTO import_scratch
                     SELECT g, 'login ' || g FROM generate_series(1, 1000) AS g$$) AS unlogged;

-- Both tables hold 1000 rows now; after a crash or a restore, only one would.
SELECT relname, relpersistence, (SELECT count(*) FROM audit_log) AS audit_rows,
       (SELECT count(*) FROM import_scratch) AS scratch_rows
FROM pg_class WHERE relname IN ('audit_log', 'import_scratch') ORDER BY relname;

-- A named WAL position to recover to, taken just before a risky migration.
SELECT pg_create_restore_point('before-migration-0042');

files.examples/02_cic.sql:
-- A case-insensitive unique index, built without blocking writes.
A: CREATE UNIQUE INDEX CONCURRENTLY users_email_lower ON users (lower(email));
-- It failed on the duplicate, and left something behind.
A: SELECT indexrelid::regclass AS index, indisvalid, indisready
   FROM pg_index WHERE indrelid = 'users'::regclass ORDER BY 1;
A: INSERT INTO users (email) VALUES ('AYSE@example.com');

-- Clean up: drop the leftover, fix the data, try again.
A: DROP INDEX CONCURRENTLY users_email_lower;
A: DELETE FROM users WHERE email <> lower(email);

-- Meanwhile B starts a read-only report that keeps one snapshot.
B: BEGIN ISOLATION LEVEL REPEATABLE READ;
B: SELECT count(*) FROM users;
A: CREATE UNIQUE INDEX CONCURRENTLY users_email_lower ON users (lower(email));
B: SELECT command, phase FROM pg_stat_progress_create_index;
B: COMMIT;
A: SELECT indexrelid::regclass AS index, indisvalid, indisready
   FROM pg_index WHERE indrelid = 'users'::regclass ORDER BY 1;

files.examples/03_fk_backfill.sql:
-- Runtime sql-nontx: every statement commits on its own, as in a migration tool.
CREATE TABLE projects (id bigint PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE requirements (id bigint PRIMARY KEY, project_code text NOT NULL);
INSERT INTO projects SELECT g, 'P' || g FROM generate_series(1, 10) AS g;
INSERT INTO requirements SELECT g, 'P' || (g % 10 + 1) FROM generate_series(1, 1000) AS g;
CREATE VIEW my_locks AS
  SELECT relation::regclass AS tbl, mode FROM pg_locks
  WHERE pid = pg_backend_pid() AND locktype = 'relation'
    AND relation IN ('projects'::regclass, 'requirements'::regclass);

-- Goal: replace project_code with a real foreign key. Expand: a nullable column.
ALTER TABLE requirements ADD COLUMN project_id bigint;

-- Guard new writes now, check old rows later.
BEGIN;
ALTER TABLE requirements ADD CONSTRAINT requirements_project_fk
  FOREIGN KEY (project_id) REFERENCES projects NOT VALID;
SELECT * FROM my_locks ORDER BY tbl, mode;
COMMIT;

-- Backfill in batches, one transaction each, so no lock is held for long.
CREATE PROCEDURE backfill_project_id(batch int) LANGUAGE plpgsql AS $$
DECLARE n int;
BEGIN
  LOOP
    UPDATE requirements r SET project_id = p.id
    FROM projects p
    WHERE p.code = r.project_code
      AND r.id IN (SELECT id FROM requirements WHERE project_id IS NULL
                   ORDER BY id LIMIT batch);
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    COMMIT;
    RAISE NOTICE 'committed a batch of % rows', n;
  END LOOP;
END $$;
CALL backfill_project_id(400);

-- Now check the old rows, under a lock that lets reads and writes continue.
BEGIN;
ALTER TABLE requirements VALIDATE CONSTRAINT requirements_project_fk;
SELECT * FROM my_locks ORDER BY tbl, mode;
COMMIT;
